class Solution:
    def minOperations(self, nums: List[int]) -> int:
        ans = 0
        while any(nums):
            for i, x in enumerate(nums):
                if x & 1:
                    nums[i] -= 1
                    ans += 1
            if any(nums):
                ans += 1
                for i in range(len(nums)):
                    nums[i] //= 2
        return ans

