class Solution {
public:
    int minOperations(vector<int>& nums) {
        int ans = 0;
        while (true) {
            for (int& x : nums) {
                if (x & 1) {
                    --x;
                    ++ans;
                }
            }
            bool any = false;
            for (int x : nums) {
                if (x > 0) {
                    any = true;
                    break;
                }
            }
            if (!any) break;
            ++ans;
            for (int& x : nums) x >>= 1;
        }
        return ans;
    }
};

