class Solution {
    public int minOperations(int[] nums) {
        int ans = 0;
        while (true) {
            for (int i = 0; i < nums.length; i++) {
                if ((nums[i] & 1) == 1) {
                    nums[i]--;
                    ans++;
                }
            }
            boolean any = false;
            for (int x : nums) {
                if (x > 0) {
                    any = true;
                    break;
                }
            }
            if (!any) break;
            ans++;
            for (int i = 0; i < nums.length; i++) nums[i] >>= 1;
        }
        return ans;
    }
}

