class Solution {
public:
    int minOperations(vector<int>& nums) {
        long long ops = 0;
        int top = 0;
        for (int x : nums) {
            ops += __builtin_popcount(x);
            if (x > 0) top = max(top, 31 - __builtin_clz(x));
        }
        return (int)(ops + top);
    }
};

