class Solution {
    public int minOperations(int[] nums) {
        long ops = 0;
        int top = 0;
        for (int x : nums) {
            ops += Integer.bitCount(x);
            if (x > 0) top = Math.max(top, 31 - Integer.numberOfLeadingZeros(x));
        }
        return (int) (ops + top);
    }
}

